 95	static BvRow* bv_get(uint32_t id, BvKind kind) {
 96	  for (BvRow* row = bv_rows; row; row = row->next)
 97	    if (row->id == id) return row->kind == kind ? row : NULL;
 98	  return NULL;
 99	}
100	static BvRow* bv_add(BvKind kind, BvRow* parent) {
101	  // Keys never repeat, including after a failed creation or a freed row.
102	  if (!bv_next_id) return NULL;
103	  BvRow* row = calloc(1, sizeof(*row));
104	  if (!row) return NULL;
105	  row->id = bv_next_id++; row->kind = kind; row->parent = parent;
106	  row->next = bv_rows; bv_rows = row;
107	  return row;
108	}
109	static void bv_remove(BvRow* row) {
110	  BvRow** link = &bv_rows;
111	  while (*link != row) link = &(*link)->next;
112	  *link = row->next;
113	  while (row->uses) { BvUse* use = row->uses; row->uses = use->next; free(use); }
114	  free(row);
115	}
116	static BvRow* bv_child(uint32_t id, BvKind kind, BvRow* owner) {
117	  BvRow* row = bv_get(id, kind);
118	  return row && row->parent == owner ? row : NULL;
119	}
120	static BvRow* bv_command_device(BvRow* command) {
