122	}
123	static int bv_referenced(BvRow* buffer) {
124	  for (BvRow* row = bv_rows; row; row = row->next)
125	    for (BvUse* use = row->uses; use; use = use->next)
126	      if (use->buffer == buffer) return 1;
127	  return 0;
128	}
129	static int bv_has_children(BvRow* parent, BvKind ignored) {
130	  for (BvRow* row = bv_rows; row; row = row->next)
131	    if (row->parent == parent && row->kind != ignored) return 1;
132	  return 0;
133	}
134	static void bv_destroy_pool(BvRow* pool) {
135	  BvDevice* device = pool->parent->context;
136	  device->DestroyCommandPool(device->handle, (VkCommandPool)(uintptr_t)pool->handle, NULL);
137	  for (BvRow* row = bv_rows, *next; row; row = next) {
138	    next = row->next;
139	    if (row->parent == pool) bv_remove(row);
140	  }
141	  bv_remove(pool);
142	}
143	static void bv_destroy_device(BvRow* row) {
144	  BvDevice* device = row->context;
145	  // There are no asynchronous submissions in this initial API.
146	  for (;;) {
147	    BvRow* pool = NULL;
148	    for (BvRow* child = bv_rows; child; child = child->next)
149	      if (child->parent == row && child->kind == BV_POOL) { pool = child; break; }
150	    if (!pool) break;
151	    bv_destroy_pool(pool);
152	  }
153	  for (BvRow* child = bv_rows, *next; child; child = next) {
154	    next = child->next;
155	    if (child->parent == row && child->kind == BV_BUFFER) {
156	      device->DestroyBuffer(device->handle, (VkBuffer)(uintptr_t)child->handle, NULL);
157	      bv_remove(child);
158	    }
159	  }
160	  for (BvRow* child = bv_rows, *next; child; child = next) {
161	    next = child->next;
162	    if (child->parent == row && child->kind == BV_MEMORY) {
163	      device->FreeMemory(device->handle, (VkDeviceMemory)(uintptr_t)child->handle, NULL);
164	      bv_remove(child);
165	    }
166	  }
167	  device->DestroyDevice(device->handle, NULL); free(device); bv_remove(row);
168	}
169	static void bv_destroy_instance(BvRow* row) {
170	  BvInstance* instance = row->context;
171	  for (BvRow* child = bv_rows, *next; child; child = next) {
172	    next = child->next;
173	    if (child->parent == row && child->kind == BV_PHYSICAL) bv_remove(child);
174	  }
175	  instance->destroy(instance->handle, NULL); free(instance); bv_remove(row);
176	}
