 37	def roundtrip(+instance: V.Instance, +physical: V.PhysicalDevice, +device: V.Device, +buffer: V.Buffer, requirements: V.MemoryRequirements) -> V.Action(Unit):
 38	  V.MemoryRequirements{size, alignment, bits} = requirements
 39	  do V.Action<Unit>:
 40	    types : List<Core.MemoryType> <- V.Instance.get_physical_device_memory_properties(instance, physical)
 41	    index : U32 <- choose(Core.find_memory_type(types, bits, vk.VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT()), "No host-visible buffer memory type")
 42	    +memory : V.DeviceMemory <- V.Device.allocate_memory(device, size, index)
 43	    V.Device.bind_buffer_memory(device, buffer, memory, W.zero())
 44	    V.Device.write_memory(device, memory, W.zero(), [0, 127, 255, 17])
 45	    host : List<U32> <- V.Device.read_memory(device, memory, W.zero(), 4)
 46	    require(bytes_equal(host, [0, 127, 255, 17]), "Host memory readback mismatch")
 47	    +pool : V.CommandPool <- V.Device.create_command_pool(device)
 48	    +command : V.CommandBuffer <- V.Device.allocate_command_buffer(device, pool)
 49	    V.CommandBuffer.begin(command)
 50	    V.CommandBuffer.fill_buffer(command, buffer, W.zero(), W.of_u32(16), 707406378)
 51	    V.CommandBuffer.end(command)
 52	    V.Device.submit_and_wait(device, command)
 53	    gpu : List<U32> <- V.Device.read_memory(device, memory, W.zero(), 16)
 54	    require(bytes_equal(gpu, [42, 42, 42, 42, 42, 42, 42, 42, 42, 42, 42, 42, 42, 42, 42, 42]), "GPU fill readback mismatch")
 55	    V.Device.destroy_command_pool(device, pool)
 56	    V.Device.destroy_buffer(device, buffer)
 57	    V.Device.free_memory(device, memory)
 58	    V.Device.destroy(device)
 59	    V.Instance.destroy(instance)
 60	    V.Action.lift(Unit, IO.print("Host roundtrip and GPU buffer fill verified"))
 61	
 62	def run(+entry: V.Entry) -> V.Action(Unit):
 63	  do V.Action<Unit>:
 64	    +instance : V.Instance <- V.Entry.create_instance(entry, V.InstanceCreateInfo.default())
 65	    devices : List<V.PhysicalDevice> <- V.Instance.enumerate_physical_devices(instance)
 66	    +physical : V.PhysicalDevice <- first(devices)
 67	    families : List<(U32 & U32)> <- V.Instance.get_physical_device_queue_family_properties(instance, physical)
 68	    family : U32 <- choose(Core.find_queue_family(families, vk.VK_QUEUE_GRAPHICS_BIT()), "No graphics queue family")
 69	    +device : V.Device <- V.Instance.create_device(instance, physical, V.DeviceCreateInfo{family, []})
 70	    +buffer : V.Buffer <- V.Device.create_buffer(device, V.BufferCreateInfo{W.of_u32(16), vk.VK_BUFFER_USAGE_TRANSFER_DST_BIT()})
 71	    requirements : V.MemoryRequirements <- V.Device.get_buffer_memory_requirements(device, buffer)
 72	    roundtrip(instance, physical, device, buffer, requirements)
 73	
 74	def main() -> IO(Unit):
 75	  do IO<Unit>:
 76	    result : V.VkResult(Unit) <- V.Entry.with(Unit, entry => run(entry))
 77	    V.or_exit(Unit, result)

