541	  BvRow* owner=bv_get(bv_key(e,f[0]),BV_DEVICE);
542	  BvRow* memory=bv_child(bv_key(e,f[1]),BV_MEMORY,owner);uint64_t offset=bv_u64(e,f[2]);
543	  uint32_t count=0,capacity=64;int valid=1;uint8_t* bytes=malloc(capacity);Term list=f[3];
544	  if (!bytes) {term_sink(e,list);return io_fail(e,BV_LIMIT,"copy allocation failed");}
545	  while (term_aux(list)==CID(Con)) {
546	    Term fields[2];bv_unpack(e,list,2,fields);list=fields[1];
547	    if ((uint32_t)fields[0]>255 || count>=BV_MAX_COPY) valid=0;
548	    if (count>=BV_MAX_COPY) {term_sink(e,list);break;}
549	    if (count==capacity) {
550	      capacity*=2;uint8_t* grown=realloc(bytes,capacity);
551	      if (!grown) {term_sink(e,list);free(bytes);return io_fail(e,BV_LIMIT,"copy allocation failed");}bytes=grown;
552	    }
553	    bytes[count++]=(uint8_t)fields[0];
554	  }
555	  if (!owner || !memory || !valid) {free(bytes);return io_fail(e,valid ? BV_INVALID : BV_ARGUMENT,"invalid memory, byte value, or copy length");}
556	  if (owner->state) {free(bytes);return io_fail(e,BV_LIFETIME,"call Device.wait_idle after a failed queue wait");}
557	  if (!bv_map_range(memory,offset,count)) {free(bytes);return io_fail(e,BV_ARGUMENT,"write needs host-visible memory and an in-bounds range");}
558	  if (!count) {free(bytes);return offset<=memory->size ? bv_ok(e) : io_fail(e,BV_ARGUMENT,"copy offset out of range");}
559	  void* mapped=NULL;VkResult result=bv_map(owner,memory,&mapped);BvDevice* device=owner->context;
