564	        .memory=(VkDeviceMemory)(uintptr_t)memory->handle,.offset=0,.size=VK_WHOLE_SIZE};
565	      result=device->FlushMappedMemoryRanges(device->handle,1,&range);
566	    }
567	    device->UnmapMemory(device->handle,(VkDeviceMemory)(uintptr_t)memory->handle);
568	  }
