683	  if (owner->state) return io_fail(e,BV_LIFETIME,"call Device.wait_idle after a failed queue wait");
684	  if (command->state!=2) return io_fail(e,BV_LIFETIME,"submit needs an executable command buffer");
685	  BvDevice* device=owner->context;VkCommandBuffer handle=(VkCommandBuffer)(uintptr_t)command->handle;
686	  VkSubmitInfo submit={.sType=VK_STRUCTURE_TYPE_SUBMIT_INFO,.commandBufferCount=1,.pCommandBuffers=&handle};
687	  // A failed submission is conservatively treated as requiring completion too.
688	  command->state=3;
689	  owner->state=1;
