  7	def choose(value: Maybe<U32>, message: String) -> V.Action(U32):
  8	  match value:
  9	    case None{}:
 10	      IO.pure(V.VkResult(U32), Fail{(1, message)})
 11	    case Some{index}:
 12	      V.Action.pure(U32, index)
