 14	def first(devices: List<V.PhysicalDevice>) -> V.Action(V.PhysicalDevice):
 15	  match devices:
 16	    case Nil{}:
 17	      IO.pure(V.VkResult(V.PhysicalDevice), Fail{(1, "No Vulkan physical device")})
 18	    case Con{device, rest}:
 19	      V.Action.pure(V.PhysicalDevice, device)
