 21	def bytes_equal(left: List<U32>, right: List<U32>) -> Bool:
 22	  match left right:
 23	    case Nil{} Nil{}:
 24	      True{}
 25	    case Con{a, xs} Con{b, ys}:
 26	      Bool.and(U32.is_eq(a, b), bytes_equal(xs, ys))
 27	    case _ _:
 28	      False{}
