 30	def require(ok: Bool, message: String) -> V.Action(Unit):
 31	  match ok:
 32	    case True{}:
 33	      V.Action.pure(Unit, Unit{})
 34	    case False{}:
 35	      IO.pure(V.VkResult(Unit), Fail{(1, message)})
