180	static BvNames bv_names(Env e, Term list) {
181	  BvNames names = {NULL, 0, 1};
182	#ifdef CID(Con)
183	  while (term_aux(list) == CID(Con)) {
184	    Term fields[2]; bv_unpack(e, list, 2, fields); list = fields[1];
185	    uint64_t length = 0; char* text = io_cstr(e, fields[0], &length);
186	    if (io_nul(text, length) || names.count >= 1024) names.valid = 0;
187	    char** more = realloc(names.values, (names.count+1)*sizeof(char*));
188	    if (!more) { free(text); term_sink(e, list); names.valid = 0; break; }
189	    names.values = more; names.values[names.count++] = text;
190	  }
191	#endif
192	  return names;
193	}
