315	    free(devices); devices=NULL;
316	    result=instance->enumerate(instance->handle,&count,NULL);
317	    if (result!=VK_SUCCESS && result!=VK_INCOMPLETE) break;
318	    if (!count) {result=VK_SUCCESS;break;}
